"use client";

import * as React from "react";
import { memo, useMemo } from "react";
import { motion, useReducedMotion } from "framer-motion";
import { useContainerDimensions, ChartTooltip } from "../_shared";
import type { GaugeChartTooltipData, TooltipRenderer } from "../_shared";
import { cn } from "../../../../lib/utils";
import {
  clampValue,
  valueToAngle,
  polarToCartesian,
  describeArcPath,
  computeZoneArcs,
  GAUGE_START_ANGLE,
  GAUGE_END_ANGLE,
} from "./utils";

/**
 * Defines a colored zone region on the gauge arc.
 */
interface GaugeZone {
  /** Data value where this zone begins (inclusive). */
  readonly from: number;
  /** Data value where this zone ends (inclusive). */
  readonly to: number;
  /** CSS color string for this zone's arc segment. */
  readonly color: string;
  /** Optional label shown in the center when the needle is in this zone. */
  readonly label?: string;
}

/**
 * Props for the {@link GaugeChart} component.
 */
interface GaugeChartProps {
  /** The current value to display on the gauge. */
  readonly value: number;
  /** Minimum value of the gauge range. @default 0 */
  readonly min?: number;
  /** Maximum value of the gauge range. @default 100 */
  readonly max?: number;
  /** Array of zone objects defining color regions. */
  readonly zones: readonly GaugeZone[];
  /** Unit label shown next to the center value (e.g. `"%"`, `"GB"`). */
  readonly unit?: string;
  /** Descriptive label shown below the center value. */
  readonly label?: string;
  /** Thickness of the gauge arc stroke in pixels. @default 20 */
  readonly strokeWidth?: number;
  /** Height of the chart container in pixels. @default 300 */
  readonly height?: number;
  /** Show loading skeleton state. @default false */
  readonly loading?: boolean;
  /** Error message to display in place of the chart. @default null */
  readonly error?: string | null;
  /** Enable entrance animation for the progress arc. @default true */
  readonly animation?: boolean;
  /** Additional CSS classes to apply to the container. */
  readonly className?: string;
  readonly tooltipRenderer?: TooltipRenderer<GaugeChartTooltipData>;
}

const DEFAULT_HEIGHT = 300;
const DEFAULT_STROKE_WIDTH = 20;
const PADDING = 24;


function LoadingState({ height }: { height: number }) {
  const size = Math.min(height - PADDING * 2, 200);
  return (
    <div className="relative w-full flex items-center justify-center" style={{ height }}>
      <div
        className="rounded-full border-8 border-muted animate-pulse"
        style={{ width: size, height: size, borderTopColor: "hsl(var(--muted-foreground) / 0.3)" }}
      />
      <div
        className="absolute rounded-full bg-background"
        style={{ width: size * 0.6, height: size * 0.6 }}
      />
    </div>
  );
}

function ErrorState({ error }: { error: string }) {
  return (
    <div className="flex items-center justify-center h-64">
      <div className="text-center space-y-2">
        <div className="text-destructive font-medium">Chart Error</div>
        <div className="text-sm text-muted-foreground">{error}</div>
      </div>
    </div>
  );
}

function EmptyState() {
  return (
    <div className="flex items-center justify-center h-64">
      <div className="text-center space-y-2">
        <div className="text-muted-foreground">No Data</div>
        <div className="text-sm text-muted-foreground">Configure zones to display the gauge</div>
      </div>
    </div>
  );
}

function GaugeChartComponent({
  value,
  min = 0,
  max = 100,
  zones,
  unit,
  label,
  strokeWidth = DEFAULT_STROKE_WIDTH,
  height = DEFAULT_HEIGHT,
  loading = false,
  error = null,
  animation = true,
  className,
  tooltipRenderer,
}: GaugeChartProps) {
  const [containerRef, containerWidth] = useContainerDimensions();
  const [hovered, setHovered] = React.useState(false);
  const reduceMotion = useReducedMotion();
  const shouldAnimate = animation && !reduceMotion;

  const clampedValue = clampValue(value, min, max);

  const size = containerWidth > 0
    ? Math.min(containerWidth - PADDING * 2, height - PADDING * 2)
    : 0;
  const cx = containerWidth / 2;
  const cy = height / 2 + size * 0.1;
  const midRadius = size / 2 - strokeWidth / 2;

  const zoneArcs = useMemo(
    () => (containerWidth > 0 ? computeZoneArcs(zones, min, max) : []),
    [zones, min, max, containerWidth]
  );

  const valueAngle = useMemo(
    () => valueToAngle(clampedValue, min, max),
    [clampedValue, min, max]
  );

  const activeZone = useMemo(
    () => [...zoneArcs].reverse().find((z) => valueAngle >= z.startAngle) ?? null,
    [zoneArcs, valueAngle]
  );

  const zoneArcPaths = useMemo(
    () => zoneArcs.map((zone) => describeArcPath(cx, cy, midRadius, zone.startAngle, zone.endAngle - 0.01)),
    [zoneArcs, cx, cy, midRadius]
  );

  const bgArcPath = useMemo(
    () => (midRadius > 0 ? describeArcPath(cx, cy, midRadius, GAUGE_START_ANGLE, GAUGE_END_ANGLE - 0.01) : ''),
    [cx, cy, midRadius]
  );

  const progressArcPath = useMemo(
    () => (midRadius > 0 && clampedValue > min
      ? describeArcPath(cx, cy, midRadius, GAUGE_START_ANGLE, valueAngle)
      : ''),
    [cx, cy, midRadius, clampedValue, min, valueAngle]
  );

  const minLabelPos = useMemo(
    () => (midRadius > 0 ? polarToCartesian(cx, cy, midRadius + strokeWidth * 0.8, GAUGE_START_ANGLE) : { x: 0, y: 0 }),
    [cx, cy, midRadius, strokeWidth]
  );

  const maxLabelPos = useMemo(
    () => (midRadius > 0 ? polarToCartesian(cx, cy, midRadius + strokeWidth * 0.8, GAUGE_END_ANGLE) : { x: 0, y: 0 }),
    [cx, cy, midRadius, strokeWidth]
  );

  if (loading) return <LoadingState height={height} />;
  if (error) return <ErrorState error={error} />;
  if (!zones.length) return <EmptyState />;

  if (!containerWidth) {
    return (
      <div ref={containerRef} className={cn("relative w-full", className)} style={{ height }}>
        <div className="flex items-center justify-center h-full text-sm text-muted-foreground">
          Loading...
        </div>
      </div>
    );
  }

  return (
    <div ref={containerRef} className={cn("relative w-full", className)} style={{ height }}>
      <svg
        width="100%"
        height={height}
        className="overflow-visible"
        role="img"
        aria-label={`Gauge showing ${clampedValue}${unit ?? ""} of ${max}${unit ?? ""}`}
        onMouseEnter={() => setHovered(true)}
        onMouseLeave={() => setHovered(false)}
      >
        {/* Background arc */}
        <path
          d={bgArcPath}
          fill="none"
          stroke="currentColor"
          strokeWidth={strokeWidth}
          strokeLinecap="round"
          opacity={0.1}
        />

        {/* Zone arcs (dimmed) */}
        {zoneArcs.map((zone, i) => (
          <path
            key={i}
            d={zoneArcPaths[i]}
            fill="none"
            stroke={zone.color}
            strokeWidth={strokeWidth}
            strokeLinecap="round"
            opacity={0.2}
          />
        ))}

        {/* Progress arc */}
        {progressArcPath && (
          <motion.path
            d={progressArcPath}
            fill="none"
            strokeWidth={strokeWidth}
            strokeLinecap="round"
            style={{
              filter: activeZone ? `drop-shadow(0 0 8px ${activeZone.color})` : undefined,
            }}
            initial={{
              pathLength: shouldAnimate ? 0 : 1,
              stroke: activeZone?.color ?? "currentColor",
            }}
            animate={{
              pathLength: 1,
              stroke: activeZone?.color ?? "currentColor",
            }}
            transition={{
              pathLength: { duration: shouldAnimate ? 1.2 : 0, ease: [0.4, 0, 0.2, 1] as const },
              stroke: { duration: 0 },
            }}
          />
        )}

        {/* Min label */}
        <text
          x={minLabelPos.x}
          y={minLabelPos.y + strokeWidth}
          textAnchor="middle"
          dominantBaseline="middle"
          fontSize={11}
          className="fill-muted-foreground"
        >
          {min}
        </text>

        {/* Max label */}
        <text
          x={maxLabelPos.x}
          y={maxLabelPos.y + strokeWidth}
          textAnchor="middle"
          dominantBaseline="middle"
          fontSize={11}
          className="fill-muted-foreground"
        >
          {max}
        </text>

        {/* Center value */}
        <text
          x={cx}
          y={cy - 4}
          textAnchor="middle"
          dominantBaseline="auto"
          fontSize={36}
          fontWeight="bold"
          className="fill-foreground"
          style={{ fontVariantNumeric: "tabular-nums" }}
        >
          {clampedValue.toLocaleString()}
          {unit && (
            <tspan fontSize={20} className="fill-muted-foreground">
              {" "}{unit}
            </tspan>
          )}
        </text>

        {/* Label */}
        {label && (
          <text
            x={cx}
            y={cy + 24}
            textAnchor="middle"
            fontSize={13}
            className="fill-muted-foreground"
          >
            {label}
          </text>
        )}

        {/* Active zone label */}
        {activeZone?.label && (
          <text
            x={cx}
            y={cy + 42}
            textAnchor="middle"
            fontSize={11}
            fill={activeZone.color}
            fontWeight="600"
          >
            {activeZone.label}
          </text>
        )}
      </svg>

      {(() => {
        const percentage = max > min ? ((clampedValue - min) / (max - min)) * 100 : 0;
        const zoneData = activeZone ? (() => {
          const matchedZone = zones.find(z => z.color === activeZone.color);
          return {
            from: matchedZone?.from ?? min,
            to: matchedZone?.to ?? max,
            color: activeZone.color,
            ...(activeZone.label != null ? { label: activeZone.label } : {}),
          };
        })() : undefined;
        const tipData: GaugeChartTooltipData | null = hovered ? {
          value: clampedValue,
          min,
          max,
          percentage,
          ...(unit != null ? { unit } : {}),
          ...(label != null ? { label } : {}),
          ...(zoneData != null ? { zone: zoneData } : {}),
        } : null;

        return (
          <ChartTooltip
            visible={tipData !== null && tooltipRenderer !== undefined}
            x={cx}
            y={Math.max(8, cy - size / 2 - 60)}
            className="transform -translate-x-1/2"
          >
            {tipData && tooltipRenderer?.(tipData)}
          </ChartTooltip>
        );
      })()}
    </div>
  );
}

export const GaugeChart = memo(GaugeChartComponent);
export type { GaugeChartProps, GaugeZone };

// src/components/charts/gauge-chart/utils.ts

/** Starting angle of the gauge arc in degrees (clockwise from right). */
export const GAUGE_START_ANGLE = 135;

/** Total sweep of the gauge arc in degrees. */
export const GAUGE_TOTAL_ANGLE = 270;

/** Ending angle of the gauge arc in degrees. */
export const GAUGE_END_ANGLE = GAUGE_START_ANGLE + GAUGE_TOTAL_ANGLE;

/**
 * Clamps a value to the given [min, max] range.
 * @param value - The value to clamp.
 * @param min - The lower bound.
 * @param max - The upper bound.
 * @returns The clamped value.
 */
export function clampValue(value: number, min: number, max: number): number {
  return Math.min(Math.max(value, min), max);
}

/**
 * Converts a data value to a gauge angle in degrees.
 * @param value - The data value to convert; clamped to [min, max] internally.
 * @param min - The minimum of the data range.
 * @param max - The maximum of the data range.
 * @returns The angle in degrees along the gauge arc.
 * @throws {RangeError} If `min >= max`.
 */
export function valueToAngle(value: number, min: number, max: number): number {
  if (min >= max) {
    throw new RangeError(`valueToAngle: min (${min}) must be less than max (${max})`);
  }
  const clamped = clampValue(value, min, max);
  const fraction = (clamped - min) / (max - min);
  return GAUGE_START_ANGLE + fraction * GAUGE_TOTAL_ANGLE;
}

/**
 * Converts polar coordinates to Cartesian (x, y).
 * @param cx - Center x of the circle.
 * @param cy - Center y of the circle.
 * @param radius - Radius of the circle.
 * @param angleDegrees - Angle in degrees (0 = right, clockwise).
 * @returns The {x, y} Cartesian coordinates.
 */
export function polarToCartesian(cx: number, cy: number, radius: number, angleDegrees: number): { x: number; y: number } {
  const rad = angleDegrees * (Math.PI / 180);
  return { x: cx + radius * Math.cos(rad), y: cy + radius * Math.sin(rad) };
}

/**
 * Describes a single colored arc zone on the gauge.
 */
export interface ZoneArc {
  /** Start angle of the arc in degrees. */
  readonly startAngle: number;
  /** End angle of the arc in degrees. */
  readonly endAngle: number;
  /** CSS color string for the arc. */
  readonly color: string;
  /** Optional human-readable label for the zone. */
  readonly label?: string | undefined;
}

/**
 * Converts an array of data-range zones into angle-based arc descriptors.
 * @param zones - Zone definitions with `from`, `to`, `color`, and optional `label`.
 * @param min - The minimum of the data range.
 * @param max - The maximum of the data range.
 * @returns Array of {@link ZoneArc} objects with angle-based bounds.
 */
export function computeZoneArcs(
  zones: readonly { from: number; to: number; color: string; label?: string | undefined }[],
  min: number,
  max: number
): ZoneArc[] {
  return zones.map((zone) => {
    const arc: ZoneArc = {
      startAngle: valueToAngle(zone.from, min, max),
      endAngle: valueToAngle(zone.to, min, max),
      color: zone.color,
      ...(zone.label !== undefined ? { label: zone.label } : {}),
    };
    return arc;
  });
}

/**
 * Builds an SVG arc path string from center, radius, and angle bounds.
 *
 * @note Spans of exactly 360° cause start and end points to coincide, making
 *   the arc invisible. Spans exceeding 359.999° are clamped automatically.
 * @param cx - Center x of the circle.
 * @param cy - Center y of the circle.
 * @param radius - Radius of the arc.
 * @param startAngle - Arc start angle in degrees.
 * @param endAngle - Arc end angle in degrees.
 * @returns SVG `d` attribute string for a circular arc path.
 */
export function describeArcPath(cx: number, cy: number, radius: number, startAngle: number, endAngle: number): string {
  const clampedEnd = startAngle + Math.min(endAngle - startAngle, 359.999);
  const start = polarToCartesian(cx, cy, radius, startAngle);
  const end = polarToCartesian(cx, cy, radius, clampedEnd);
  const largeArc = clampedEnd - startAngle > 180 ? 1 : 0;
  return `M ${start.x} ${start.y} A ${radius} ${radius} 0 ${largeArc} 1 ${end.x} ${end.y}`;
}
